358	    /**
359	     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after it.
360	     * A correction rounds by the date of the claim it corrects.
361	     */
362	    public RoundingMode rounding(Claim claim) {
363	        LocalDate date = claim.date();
364	        if (claim.isCorrection() && claim.corrects() != null) {
365	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
366	            if (corrected != null) {
367	                date = corrected.date();
368	            }
369	        }
370	        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
371	    }
