373	    /** The claim's live due at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, raised to the floor; null (no rate) stays null. */
374	    public BigDecimal live(Claim claim, BigDecimal rate) {
375	        return rate == null ? null
376	                : floored(claim, claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim)));
377	    }
378	
379	    /**
380	     * A claim's figure with its late charge added on top: an open (OPEN or PENDING) claim whose due-by (fixed when it was made) is
381	     * before {@code today} gains the late percent in force on the claim's date of the figure for every full 30 days it is overdue, rounded by {@link #rounding}.
382	     * The charge is never bound by a statement, so it follows the sheet's today; null (no figure) stays null.
383	     * A correction has no late charge, nor has a deferred claim (it is not overdue until the sheet's today reaches its date).
384	     */
385	    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
386	        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today)) {
387	            return figure;
388	        }
389	        LocalDate dueBy = claim.dueBy();
390	        if (!dueBy.isBefore(today)) {
391	            return figure;
392	        }
393	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
394	        BigDecimal charge = figure.multiply(latePct(claim.sheetId(), claim.date())).multiply(BigDecimal.valueOf(periods))
395	                .movePointLeft(2).setScale(2, rounding(claim));
396	        return figure.add(charge);
397	    }
