399	    /** The claim's live due raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
400	    public BigDecimal floored(Claim claim, BigDecimal due) {
401	        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
402	    }
