485	public class ValidateSettings {
486	
487	    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
488	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");
489	
490	    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
491	    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
492	    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
493	    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
494	    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
495	    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
496	    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
497	    // and only a grade (A, B or C) may have them.
498	    // The period numbering from-date is the same: missing is left as it is, blank is off, otherwise a yyyy-MM-dd date.
499	    // The cap is missing: left as it is, blank: none, otherwise an amount of 0.00 or more with up to two decimals.
500	    // A from-date, given by setting key, is blank (the sheet's today) or a yyyy-MM-dd date, and only a dated setting has one.
501	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
502	            Out<SheetSettings> settingsOut) throws InvalidSettingException {
503	        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
504	        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
505	            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
506	        }
507	        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
508	        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
509	            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
510	        }
511	        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
512	        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
513	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
514	        }
515	        SortedMap<String, String> gradeTerms = new TreeMap<>();
516	        if (body != null && body.gradeTerms() != null) {
517	            for (Map.Entry<String, String> entry : body.gradeTerms().entrySet()) {
518	                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
519	                String days = entry.getValue() == null ? "" : entry.getValue().trim();
520	                if (days.isEmpty()) {
521	                    continue;
522	                }
523	                if (!Settings.GRADES.contains(grade)) {
524	                    throw new InvalidSettingException("Terms can be set only for grade A, B or C.");
525	                }
526	                if (!DAYS.matcher(days).matches()) {
527	                    throw new InvalidSettingException("The terms of grade " + grade + " must be a whole number of days, 0 or more.");
528	                }
529	                gradeTerms.put(grade, Integer.toString(Integer.parseInt(days)));
530	            }
531	        }
532	        String latePct = body == null || body.latePct() == null ? "" : body.latePct().trim();
533	        if (!latePct.isEmpty() && !AMOUNT.matcher(latePct).matches()) {
534	            throw new InvalidSettingException("The late percent must be a percent of 0.00 or more, with up to two decimals.");
535	        }
536	        String policyDate = body == null || body.policyDate() == null ? null : body.policyDate().trim();
537	        if (policyDate != null && !policyDate.isEmpty()) {
538	            try {
539	                policyDate = LocalDate.parse(policyDate).toString();
540	            } catch (DateTimeParseException e) {
541	                throw new InvalidSettingException("The policy date must be a date (yyyy-mm-dd).");
542	            }
543	        }
544	        String numberingFrom = body == null || body.periodNumberingFrom() == null ? null : body.periodNumberingFrom().trim();
545	        if (numberingFrom != null && !numberingFrom.isEmpty()) {
546	            try {
547	                numberingFrom = LocalDate.parse(numberingFrom).toString();
548	            } catch (DateTimeParseException e) {
549	                throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd).");
550	            }
551	        }
552	        String cap = body == null || body.cap() == null ? null : body.cap().trim();
553	        if (cap != null && !cap.isEmpty()) {
554	            if (!AMOUNT.matcher(cap).matches()) {
555	                throw new InvalidSettingException("The cap must be an amount of 0.00 or more, with up to two decimals.");
556	            }
557	            cap = twoDecimals(cap);
558	        }
559	        Map<String, LocalDate> from = new java.util.HashMap<>();
560	        if (body != null && body.from() != null) {
561	            for (Map.Entry<String, String> entry : body.from().entrySet()) {
562	                String key = entry.getKey() == null ? "" : entry.getKey().trim();
563	                String date = entry.getValue() == null ? "" : entry.getValue().trim();
564	                if (date.isEmpty()) {
565	                    continue;
566	                }
567	                if (!Settings.DATED.contains(key)) {
568	                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
569	                }
570	                try {
571	                    from.put(key, LocalDate.parse(date));
572	                } catch (DateTimeParseException e) {
573	                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
574	                }
575	            }
576	        }
577	        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !latePct.isEmpty() || policyDate != null
578	                || numberingFrom != null || cap != null;
579	        if (typed == null && !others) {
580	            typed = "";
581	        }
582	        String limit = typed == null || (typed.isEmpty() && others) ? null
583	                : typed.isEmpty() ? "" : twoDecimals(typed);
584	        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor),
585	                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)),
586	                latePct.isEmpty() ? null : twoDecimals(latePct), policyDate, numberingFrom, cap, gradeTerms, from));
587	    }
588	
589	    private static String twoDecimals(String amount) {
590	        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
591	    }
592	}
593	-- A setting that carries a figure (the clerk limit, the floor, the terms and each grade's terms, the late percent,
594	-- the cap) is dated: one value per from-date, in force from that date until the next one. A blank value is none
595	-- (no clerk limit, no cap). The policy date and the period numbering from-date stay undated, in setting.
596	CREATE TABLE setting_from (
597	    sheet_id      VARCHAR(255) NOT NULL,
598	    setting_key   VARCHAR(64)  NOT NULL,
599	    from_date     DATE         NOT NULL,
600	    setting_value VARCHAR(255) NOT NULL,
601	    PRIMARY KEY (sheet_id, setting_key, from_date)
602	);
603	-- A value saved before settings were dated was in force on every date.
604	INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
605	    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM setting
606	    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
607	DELETE FROM setting
608	    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
609	-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches it the claim counts
610	-- in no total, is not overdue, cannot be settled and is left unbound by a statement. Null: never deferred.
611	ALTER TABLE claim ADD COLUMN deferred_until DATE;
